const $=id=>document.getElementById(id);let tf='1h',candles=[],analysis,source='demo',request=0,imported=null,saved=[];
try{saved=JSON.parse(localStorage.getItem('structure-setups')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}
const format=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:n<10?4:2});
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const durations={'5m':300000,'15m':900000,'1h':3600000,'4h':14400000,'1d':86400000};
function demo(){const bases={BTCUSDT:67800,ETHUSDT:3450,SOLUSDT:162,BNBUSDT:590},base=bases[$('contract').value];let seed=42+Object.keys(durations).indexOf(tf)*117+Object.keys(bases).indexOf($('contract').value)*91;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};let p=base*.96;const end=Math.floor(Date.now()/durations[tf])*durations[tf];return Array.from({length:240},(_,i)=>{const o=p,drift=(i>170?.0008:.00005)+Math.sin(i/15)*.0007,c=o*(1+drift+(rand()-.47)*.007),h=Math.max(o,c)+base*rand()*.002,l=Math.min(o,c)-base*rand()*.002;p=c;return {t:end-(240-i)*durations[tf],o,h,l,c,v:rand()*1000}})}
async function load(){const token=++request;$('analyze').disabled=true;$('analyze').textContent='Analyzing…';try{source=$('dataMode').value;
 if(source==='live'){const response=await fetch(`https://fapi.binance.com/fapi/v1/klines?symbol=${$('contract').value}&interval=${tf}&limit=300`,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Exchange returned '+response.status);const rows=await response.json();if(!Array.isArray(rows))throw Error('Invalid exchange response');if(token!==request)return;candles=rows.filter(r=>r[6]<Date.now()).map(r=>({t:+r[0],o:+r[1],h:+r[2],l:+r[3],c:+r[4],v:+r[5]}));}
 else if(source==='csv'){if(!imported)throw Error('Import candles first.');candles=imported.rows}else candles=demo();
 if(token!==request)return;analysis=analyzeCandles(candles);render();$('message').textContent=source==='demo'?'Sample candles are simulated and do not represent current market prices.':source==='csv'?`Imported ${imported.name}. Latest closed candle: ${new Date(candles.at(-1).t).toISOString()}. Verify contract and timeframe before use.`:`Binance USDⓈ-M · Snapshot fetched ${new Date().toLocaleTimeString()} · Latest closed candle ${new Date(candles.at(-1).t).toISOString()} · Refresh manually.`;
 }catch(e){if(token!==request)return;analysis=null;$('message').textContent=`Analysis unavailable: ${e.message}. Choose sample data or import a CSV. Previous results have been cleared.`;['lastPrice','trend','range','atr','score','bias'].forEach(id=>$(id).textContent='—');$('sourceBadge').textContent='● DATA UNAVAILABLE';$('chart').innerHTML='';$('signals').innerHTML='';$('tradeLevels').innerHTML='';$('sizing').innerHTML='';$('scorebar').style.width='0';$('reason').textContent='No valid analysis. Load data to continue.';$('save').disabled=true;}finally{if(token===request){$('analyze').disabled=false;$('analyze').textContent='Analyze market'}}}
function render(){const a=analysis,c=candles.at(-1),first=candles.at(-25),pct=(c.c-first.c)/first.c*100;$('sourceBadge').textContent=source==='demo'?'● SAMPLE DATA':source==='csv'?'● IMPORTED DATA':'● EXCHANGE SNAPSHOT';$('save').disabled=false;$('lastPrice').textContent='$'+format(c.c);$('change').textContent=(pct>=0?'+':'')+pct.toFixed(2)+'% · last 24 candles';$('change').style.color=pct>=0?'var(--teal)':'var(--red)';$('trend').textContent=a.trend===1?'Bullish':a.trend===-1?'Bearish':'Ranging';$('trend').style.color=a.trend===1?'var(--teal)':a.trend===-1?'var(--red)':'var(--muted)';$('range').textContent=c.c<a.mid?'Discount':'Premium';$('rangeNote').textContent=((c.c-a.bottom)/(a.top-a.bottom)*100).toFixed(0)+'% of 60-candle range';$('atr').textContent='$'+format(a.atr);$('bias').textContent=a.wait?'Wait for confirmation':a.dir===1?'Buy / Long bias':'Sell / Short bias';$('bias').style.color=a.wait?'#d9bc7b':a.dir===1?'var(--green)':'var(--red)';$('reason').textContent=a.reason;$('score').textContent=Math.min(100,a.score)+' / 100';$('scorebar').style.width=Math.min(100,a.score)+'%';$('tradeLevels').innerHTML=[['Planned entry',a.entry,''],['Stop loss',a.stop,'var(--red)'],['Take profit 1 · 1R',a.tp1,'var(--teal)'],['Take profit 2 · 2R',a.tp2,'var(--green)']].map(([s,v,color])=>`<div><span>${s}</span><b style="color:${color}">${format(v)}</b></div>`).join('');
 $('chartTitle').textContent=source==='csv'?imported.contract:$('contract').selectedOptions[0].textContent;$('chartMeta').textContent=`${source==='csv'?'Imported timeframe':tf.toUpperCase()} · Closed candles · UTC`;$('candleCount').textContent=candles.length+' candles';
 let count=0;$('signals').innerHTML=definitions.map(([name])=>{const event=a.recent.filter(e=>e.name===name).at(-1);const range=name==='Premium / Discount';if(event||range)count++;return `<div class="signal ${!event&&!range?'no':''}"><div class="signal-icon">${event||range?'✓':'·'}</div><div><b>${name}</b><p>${escapeHTML(event?event.detail:range?`${c.c<a.mid?'Below':'Above'} midpoint ${format(a.mid)}`:'No recent match')}</p></div><span class="state">${event?(event.dir===1?'Bullish':event.dir===-1?'Bearish':'Neutral'):range?'Context':'—'}</span></div>`}).join('');$('signalsCount').textContent=count+' / 14 DETECTED';draw();size();}
function draw(){if(!analysis)return;const a=analysis,visible=candles.slice(-90),W=920,H=390,left=16,right=87,top=24,bottom=35,cw=(W-left-right)/visible.length;let values=visible.flatMap(c=>[c.h,c.l]);if($('levels').checked)values.push(a.entry,a.stop,a.tp1,a.tp2);const low=Math.min(...values)-a.atr*.6,high=Math.max(...values)+a.atr*.6,y=p=>top+(high-p)/(high-low)*(H-top-bottom),x=i=>left+i*cw+cw/2;
 let svg=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">`;
 for(let i=0;i<6;i++){let p=low+(high-low)*i/5,yy=y(p);svg+=`<line x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}" stroke="#222c36" stroke-dasharray="2 5"/><text x="${W-right+10}" y="${yy+4}" fill="#788698" font-size="11" font-family="sans-serif">${format(p)}</text>`}
 const middle=y(a.mid);if(middle>top&&middle<H-bottom)svg+=`<line x1="${left}" x2="${W-right}" y1="${middle}" y2="${middle}" stroke="#546173" stroke-dasharray="5 6"/><text x="22" y="${middle-6}" fill="#8a97a9" font-size="10">EQUILIBRIUM</text>`;
 if($('zones').checked)for(const z of a.zones.slice(-8)){const start=Math.max(0,z.i-(candles.length-90)),yy=y(z.high),hh=y(z.low)-yy;if(yy<0||yy>H-bottom)continue;const color=z.dir===1?'#43cda5':'#ef7c8e';svg+=`<rect x="${x(start)}" y="${yy}" width="${W-right-x(start)}" height="${Math.max(hh,2)}" fill="${color}" fill-opacity=".09" stroke="${color}" stroke-opacity=".25"/><text x="${x(start)+5}" y="${yy+12}" fill="${color}" font-size="10">${z.name==='Order Block'?'OB':'FVG'}</text>`}
 visible.forEach((c,i)=>{let color=c.c>=c.o?'#43cda5':'#e37f8e';svg+=`<g data-i="${i}"><line x1="${x(i)}" x2="${x(i)}" y1="${y(c.h)}" y2="${y(c.l)}" stroke="${color}"/><rect x="${x(i)-cw*.29}" y="${y(Math.max(c.o,c.c))}" width="${cw*.58}" height="${Math.max(1,Math.abs(y(c.o)-y(c.c)))}" fill="${color}"/><rect x="${x(i)-cw/2}" y="${top}" width="${cw}" height="${H-top-bottom}" fill="transparent"/></g>`;if(i%18===0)svg+=`<text x="${x(i)}" y="${H-10}" fill="#788698" font-size="10">${new Date(c.t).toISOString().slice(5,16).replace('T',' ')}</text>`});
 if($('levels').checked)for(const [name,p,color] of [['ENTRY',a.entry,'#b6c4d8'],['SL',a.stop,'#ef7c8e'],['TP 1',a.tp1,'#43cda5'],['TP 2',a.tp2,'#a4ef63']]){const yy=y(p);svg+=`<line x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}" stroke="${color}" stroke-dasharray="6 5" opacity=".75"/><rect x="${W-right-57}" y="${yy-9}" width="55" height="18" rx="3" fill="${color}"/><text x="${W-right-51}" y="${yy+4}" fill="#102019" font-size="10" font-weight="bold">${name}</text>`}
 $('chart').innerHTML=svg+'</svg>';$('chart').querySelectorAll('g[data-i]').forEach(el=>el.addEventListener('pointerenter',()=>{let c=visible[+el.dataset.i];$('candleInfo').textContent=`${new Date(c.t).toISOString().slice(0,16).replace('T',' ')} UTC · O ${format(c.o)} H ${format(c.h)} L ${format(c.l)} C ${format(c.c)}`}));}
function size(){if(!analysis)return;const balance=+$('balance').value,risk=+$('risk').value,lev=+$('leverage').value,fees=+$('fees').value;if(balance<=0||risk<=0||risk>5||lev<1||lev>125||fees<0||fees>5||![balance,risk,lev,fees].every(Number.isFinite)){$('sizing').textContent='Enter valid values: risk 0–5%, leverage 1–125×, fees 0–5%.';return}const budget=balance*risk/100,unitRisk=Math.abs(analysis.entry-analysis.stop)+analysis.entry*fees/100,qty=budget/unitRisk,notional=qty*analysis.entry,margin=notional/lev;$('sizing').innerHTML=[['Planned maximum loss','$'+format(budget)],['Position size',qty.toFixed(5)+' units'],['Notional exposure','$'+format(notional)],['Estimated initial margin','$'+format(margin)]].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')+(margin>balance?'<p style="color:var(--red);font-size:12px;margin-top:12px">Insufficient balance for this initial margin. Reduce risk or position size.</p>':'');}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2800)}
function view(id){['desk','journal','guide'].forEach(v=>$(v).hidden=v!==id);document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('viewName').textContent={desk:'Market overview',journal:'Saved setups',guide:'Strategy library'}[id];if(id==='journal')renderSaved()}
function renderSaved(){$('savedCount').textContent=saved.length;$('savedList').innerHTML=saved.length?saved.map((s,i)=>`<article class="panel"><div><h2>${escapeHTML(s.contract)} · ${escapeHTML(s.bias)} <span class="tag">${escapeHTML(s.source.toUpperCase())}</span></h2><p>${escapeHTML(s.tf)} · ${new Date(s.time).toLocaleString()}<br>Entry ${format(s.entry)} · SL ${format(s.stop)} · TP1 ${format(s.tp1)} · TP2 ${format(s.tp2)}</p></div><button class="secondary" data-delete="${i}">Delete</button></article>`).join(''):'<div class="panel guide-intro">No setups saved yet. Analyze a contract and save a snapshot of your plan.</div>';$('savedList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{saved.splice(+b.dataset.delete,1);persist();renderSaved()})}
function persist(){try{localStorage.setItem('structure-setups',JSON.stringify(saved));return true}catch{toast('Browser storage unavailable. Export your setups to keep them.');return false}}
$('save').onclick=()=>{if(!analysis)return;saved.unshift({contract:source==='csv'?imported.contract:$('contract').value,tf:source==='csv'?'CSV':tf,source,time:Date.now(),bias:analysis.wait?'Wait':analysis.dir===1?'Long':'Short',entry:analysis.entry,stop:analysis.stop,tp1:analysis.tp1,tp2:analysis.tp2});if(persist())toast('Setup saved to your research journal');renderSaved()};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='structure-desk-setups.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>view(b.dataset.view));$('guideButton').onclick=()=>view('guide');$('analyze').onclick=load;$('contract').onchange=()=>{if($('dataMode').value==='csv')$('dataMode').value='demo';load()};$('dataMode').onchange=load;
document.querySelectorAll('[data-tf]').forEach(b=>b.onclick=()=>{tf=b.dataset.tf;document.querySelectorAll('[data-tf]').forEach(x=>x.classList.toggle('selected',x===b));if($('dataMode').value==='csv')$('dataMode').value='demo';load()});['zones','levels'].forEach(id=>$(id).onchange=draw);['balance','risk','leverage','fees'].forEach(id=>$(id).oninput=size);
$('importButton').onclick=()=>{toast('CSV: time,open,high,low,close,volume · 60+ closed candles · UTC');$('file').click()};
$('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Maximum CSV size is 5 MB');const lines=(await file.text()).trim().split(/\r?\n/),headers=lines.shift().toLowerCase().replace(/^\uFEFF/,'').split(',').map(x=>x.trim());const index=n=>headers.indexOf(n),required=['time','open','high','low','close'];if(required.some(h=>index(h)<0))throw Error('Header must contain time,open,high,low,close (volume optional)');let rows=lines.filter(s=>s.trim()).map((line,i)=>{const v=line.split(',').map(x=>x.trim()),raw=v[index('time')],numeric=Number(raw),t=Number.isFinite(numeric)?(numeric<1e12?numeric*1000:numeric):Date.parse(raw.endsWith('Z')||/[+-]\d\d:\d\d$/.test(raw)?raw:raw+'Z'),o=+v[index('open')],h=+v[index('high')],l=+v[index('low')],c=+v[index('close')];if(![t,o,h,l,c].every(Number.isFinite)||Math.min(o,h,l,c)<=0||h<Math.max(o,c)||l>Math.min(o,c)||h<l)throw Error('Invalid OHLC or time on row '+(i+2));return {t,o,h,l,c,v:index('volume')<0?0:+v[index('volume')]}});rows.sort((a,b)=>a.t-b.t);if(rows.some((r,i)=>i&&r.t===rows[i-1].t))throw Error('Duplicate candle timestamps');const step=rows.length>1?rows.at(-1).t-rows.at(-2).t:0;rows=rows.filter(r=>r.t+step<Date.now());if(rows.length<60)throw Error('Need at least 60 closed candles');if(rows.some((r,i)=>i&&r.t-rows[i-1].t!==step))throw Error('Candles must have a consistent interval without gaps');const contract=prompt('Contract label for this CSV (for example BTCUSDT)',file.name.replace(/\.csv$/i,''));if(!contract)return;imported={rows:rows.slice(-1500),name:file.name,contract};if(!$('dataMode').querySelector('[value="csv"]'))$('dataMode').add(new Option('Imported CSV','csv'));$('dataMode').value='csv';await load()}catch(err){toast(err.message)}finally{e.target.value=''}};
$('library').innerHTML=definitions.map(([n,d])=>`<article class="panel"><h2>${n}</h2><p>${d}</p></article>`).join('');renderSaved();load();
